-- ===== 000_database.sql =====
-- PostgreSQL: baza products
-- Skrypty są idempotentne - można je uruchamiać wielokrotnie, osobno lub scalone (merge_files.cmd).
-- Ten plik wymaga psql (\gexec, \connect); pozostałe to czysty SQL - uruchamiać w bazie products.

SELECT 'CREATE DATABASE products'
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = 'products')\gexec

\connect products

-- ===== 001_currencies.sql =====
-- Słownik walut
CREATE TABLE IF NOT EXISTS "Currencies"
(
    "Id"       smallint     NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Code"     varchar(3)   NOT NULL, -- ISO 4217
    "Name"     varchar(100) NOT NULL,
    "IsActive" boolean      NOT NULL DEFAULT true,

    CONSTRAINT "PK_Currencies" PRIMARY KEY ("Id"),
    CONSTRAINT "AK_Currencies_Code" UNIQUE ("Code")
);

INSERT INTO "Currencies" ("Id", "Code", "Name")
VALUES (1, 'PLN', 'Polski złoty'),
       (2, 'EUR', 'Euro'),
       (3, 'USD', 'Dolar amerykański')
ON CONFLICT ("Code") DO NOTHING;

-- jawne Id nie przesuwają sekwencji identity - wyrównanie, żeby kolejne waluty nie kolidowały
SELECT setval(pg_get_serial_sequence('"Currencies"', 'Id'), (SELECT max("Id") FROM "Currencies"));

-- ===== 002_products.sql =====
-- Produkty
CREATE TABLE IF NOT EXISTS "Products"
(
    "Id"           uuid           NOT NULL DEFAULT uuidv7(),
    "Name"         varchar(200)   NOT NULL,
    "Price"        numeric(18, 2) NOT NULL,
    "Currency"     varchar(3)     NOT NULL,
    "CreatedAtUtc" timestamptz    NOT NULL DEFAULT now(),
    "UpdatedAtUtc" timestamptz    NOT NULL DEFAULT now(),
    "Version"      integer        NOT NULL DEFAULT 1, -- zwiększana przy każdej zmianie

    CONSTRAINT "PK_Products" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Products_Currencies_Currency" FOREIGN KEY ("Currency") REFERENCES "Currencies" ("Code"),
    CONSTRAINT "CK_Products_Name_NotEmpty" CHECK (TRIM("Name") <> ''),
    CONSTRAINT "CK_Products_Price_Positive" CHECK ("Price" > 0)
);

-- lista od najnowszych (GET /api/products) - indeks czytany wstecz, Id rozstrzyga równe daty
CREATE INDEX IF NOT EXISTS "IX_Products_CreatedAtUtc_Id"
    ON "Products" ("CreatedAtUtc", "Id");

-- ===== 003_product_price_history.sql =====
-- Historia zmian cen - zapisywana w tej samej transakcji co zmiana ceny
CREATE TABLE IF NOT EXISTS "ProductPriceHistory"
(
    "Id"           bigint         NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "ProductId"    uuid           NOT NULL,
    "OldPrice"     numeric(18, 2) NOT NULL,
    "OldCurrency"  varchar(3)     NOT NULL,
    "NewPrice"     numeric(18, 2) NOT NULL,
    "NewCurrency"  varchar(3)     NOT NULL,
    "ChangedAtUtc" timestamptz    NOT NULL,

    CONSTRAINT "PK_ProductPriceHistory" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ProductPriceHistory_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id")
);

CREATE INDEX IF NOT EXISTS "IX_ProductPriceHistory_ProductId_ChangedAtUtc"
    ON "ProductPriceHistory" ("ProductId", "ChangedAtUtc");

-- ===== 004_outbox_messages.sql =====
-- Transactional Outbox - zdarzenia czekające na wysyłkę do Kafki
CREATE TABLE IF NOT EXISTS "OutboxMessages"
(
    "Id"             bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY, -- kolejność wysyłki
    "Type"           varchar(200)  NOT NULL, -- typ zdarzenia z wersją schematu (nagłówek Kafki event-type)
    "Topic"          varchar(200)  NOT NULL,
    "MessageKey"     varchar(100)  NOT NULL, -- klucz partycji Kafki (ProductId) - kolejność per produkt
    "Payload"        text          NOT NULL, -- JSON zdarzenia (text, bo nie odpytujemy jego zawartości)
    "TraceParent"    varchar(55)   NULL,     -- W3C trace context żądania, które zapisało zdarzenie
    "OccurredAtUtc"  timestamptz   NOT NULL,
    "ProcessedAtUtc" timestamptz   NULL,
    "Attempts"       integer       NOT NULL DEFAULT 0, -- błędy trwałe; limit -> dead-letter
    "LastError"      varchar(2000) NULL,

    CONSTRAINT "PK_OutboxMessages" PRIMARY KEY ("Id")
);

-- mały indeks tylko z nieprzetworzonymi wiadomościami
CREATE INDEX IF NOT EXISTS "IX_OutboxMessages_Pending"
    ON "OutboxMessages" ("Id")
    WHERE "ProcessedAtUtc" IS NULL;

-- retencja: usuwanie starych wysłanych; nowe (jeszcze niewysłane) wiadomości do indeksu nie trafiają
CREATE INDEX IF NOT EXISTS "IX_OutboxMessages_ProcessedAtUtc"
    ON "OutboxMessages" ("ProcessedAtUtc")
    WHERE "ProcessedAtUtc" IS NOT NULL;

-- ===== 005_processed_events.sql =====
-- Idempotentny konsument (inbox) - zdarzenia już obsłużone przez danego odbiorcę (grupę konsumentów Kafki)
CREATE TABLE IF NOT EXISTS "ProcessedEvents"
(
    "Consumer"       varchar(100) NOT NULL,
    "EventId"        uuid         NOT NULL,
    "ProcessedAtUtc" timestamptz  NOT NULL,

    CONSTRAINT "PK_ProcessedEvents" PRIMARY KEY ("Consumer", "EventId")
);

-- retencja: usuwanie starych wpisów
CREATE INDEX IF NOT EXISTS "IX_ProcessedEvents_ProcessedAtUtc"
    ON "ProcessedEvents" ("ProcessedAtUtc");

-- ===== 006_idempotency_keys.sql =====
-- Klucze idempotencji POST /api/products (nagłówek Idempotency-Key) - ponowione żądanie dostaje utworzony już produkt
CREATE TABLE IF NOT EXISTS "IdempotencyKeys"
(
    "Key"          varchar(100) NOT NULL,
    "ProductId"    uuid         NOT NULL,
    "RequestHash"  bytea        NOT NULL, -- SHA-256 treści żądania: ten sam klucz z inną treścią to błąd 422
    "CreatedAtUtc" timestamptz  NOT NULL DEFAULT now(),

    CONSTRAINT "PK_IdempotencyKeys" PRIMARY KEY ("Key"),
    CONSTRAINT "FK_IdempotencyKeys_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id")
);

-- retencja: klucze ważne ograniczony czas
CREATE INDEX IF NOT EXISTS "IX_IdempotencyKeys_CreatedAtUtc"
    ON "IdempotencyKeys" ("CreatedAtUtc");

-- ===== 007_ef_migrations_history.sql =====
-- Historia migracji EF Core: baza ze skryptów jest dla EF już zmigrowana, więc warianty mogą na zmianę używać
-- jednej bazy - schemat z migracji (Database:Schema=Migrations) albo z tych skryptów (Scripts).
-- Nowa migracja EF = skrypt z tą samą zmianą schematu + jej Id poniżej (sprawdza to test SchemaSourcesTests).
CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory"
(
    "MigrationId"    varchar(150) NOT NULL,
    "ProductVersion" varchar(32)  NOT NULL,

    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261015185859_InitialCreate', '10.0.13'),
       ('20261016090107_ProductListIndex', '10.0.13')
ON CONFLICT ("MigrationId") DO NOTHING;

